#!/bin/bash
set -euo pipefail

BASE_DIR=$(pwd)
CONFIG_DIR="$BASE_DIR/config"
WORK_DIR="$BASE_DIR/work_data"

copy_if_missing() {
    local src="$1"
    local dst="$2"
    if [ ! -f "$dst" ] && [ -f "$src" ]; then
        cp "$src" "$dst"
        echo "🧩 Creado $(realpath --relative-to="$BASE_DIR" "$dst") desde $(realpath --relative-to="$BASE_DIR" "$src")"
    fi
}

