    'mass_config.py': '# ==========================================\n# ⚙️ UNIT3D MASS EDITION SUITE - CONFIG\n# ==========================================\n# Namespace propio en el .env: prefijo ME_\n# Uso standalone: edita los fallbacks de os.getenv() directamente.\n# Uso via singularity/Docker: los ME_* del .env tienen prioridad.\n\nimport os\nfrom pathlib import Path\n\ntry:\n    from dotenv import load_dotenv\n    _here = Path(__file__).resolve().parent\n    for _ep in [_here / ".env", _here / "../../.env", Path("/app/.env")]:\n        if _ep.exists():\n            load_dotenv(_ep)\n            break\nexcept ImportError:\n    pass\n\n# ─── 1. Credenciales y Tracker (namespace ME_) ────────────────────────────────\nBASE_URL          = os.getenv("ME_TRACKER_URL",         "https://nobs.rawsmoke.net")\nUSERNAME          = os.getenv("ME_TRACKER_USERNAME",    "TuUsuario")\nCOOKIE_NAME       = os.getenv("ME_TRACKER_COOKIE_NAME", "nuclear_order_bit_syndicate_session")\nCOOKIE_VALUE      = os.getenv("ME_TRACKER_COOKIE",      "")\nCUSTOM_USER_AGENT = os.getenv("ME_CUSTOM_USER_AGENT",   "undici")\nTRACKER_ABBREV    = os.getenv("ME_TRACKER_DEFAULT",     "NOBS")\n\n# ─── 2. APIs de imágenes (namespace ME_) ──────────────────────────────────────\nIMGBB_API      = os.getenv("ME_IMGBB_API",     "")\nPTSCREENS_API  = os.getenv("ME_PTSCREENS_API", "")\n\n# ─── 3. Rutas (namespace ME_) ─────────────────────────────────────────────────\nTMP_DIR_PATH = os.getenv("ME_TMP_ROOT", "/app/RawLoadrr/tmp")\n\n# ─── 4. Rango de IDs (vars ME-only, sin riesgo de colisión) ──────────────────\nID_INICIO = int(os.getenv("ID_START", "14"))\nID_FIN    = int(os.getenv("ID_END",   "2000"))\nID_FILE   = os.getenv("ID_FILENAME",  "ids.txt")\n\n# ─── 5. Modo de edición y textos (vars ME-only) ───────────────────────────────\nEDIT_MODE        = os.getenv("EDIT_MODE",        "BANNER_URL")\nBANNER_URL_NUEVA = os.getenv("BANNER_URL_NUEVA", "")\nBANNER_IMG_NUEVA = os.getenv("BANNER_IMG_NUEVA", "")\nFIRMA_TEXT_NUEVA = os.getenv("FIRMA_TEXT_NUEVA", "")\nFIRMA_FULL_NUEVA = os.getenv("FIRMA_FULL_NUEVA", "")\nFIND_URL         = os.getenv("FIND_URL",         "")\nREPLACE_URL      = os.getenv("REPLACE_URL",      "")\nBLOCK_VIEJO      = os.getenv("BLOCK_VIEJO",      "")\nBLOCK_NUEVO      = os.getenv("BLOCK_NUEVO",      "")\n\n# ─── 6. Textos estáticos ──────────────────────────────────────────────────────\nMSG_VIEJO = "[center][b]PLEASE SEED MILNUEVE FAMILY[/b][/center]"\nMSG_NUEVO = "[center][b]🌱 ¡La magia del P2P eres tú! Por favor, quédate compartiendo (seeding) para mantener viva la comunidad. 🌱[/b][/center]"\n\nBANNER_VIEJO = "[center][url=https://codeberg.org/CvT/Uploadrr][img=400]https://i.ibb.co/2NVWb0c/uploadrr.webp[/img][/url][/center]"\nBANNER_NUEVO = "[center][url=https://codeberg.org/RawSmoke/Singularity][img=400]https://i.ibb.co/0RrzLmSr/RAW-bruma-servers.png[/img][/url][/center]"\n\nFIRMAS_VIEJAS = [\n    "[center][b]PLEASE SEED MILNUEVE FAMILY[/b][/center]",\n    "[center][url=https://codeberg.org/CvT/Uploadrr][img=400]https://i.ibb.co/2NVWb0c/uploadrr.webp[/img][/url][/center]",\n]\n\n# ─── 7. Settings del bot ──────────────────────────────────────────────────────\nDELAY_MIN = float(os.getenv("ME_DELAY_MIN", "4.5"))\nDELAY_MAX = float(os.getenv("ME_DELAY_MAX", "7.5"))\n\n# ─── 8. Utilidades ────────────────────────────────────────────────────────────\ndef get_target_ids():\n    """Retorna la lista final de IDs a procesar (de ids.txt filtrada por rango)."""\n    ids = []\n    if os.path.exists(ID_FILE):\n        with open(ID_FILE, "r") as f:\n            for line in f:\n                stripped = line.strip()\n                if not stripped:\n                    continue\n                try:\n                    int(stripped)\n                    ids.append(stripped)\n                except ValueError:\n                    pass\n    if ids:\n        return [tid for tid in ids if ID_INICIO <= int(tid) <= ID_FIN]\n    return [str(i) for i in range(ID_INICIO, ID_FIN + 1)]\n',
}
